### Python

```python
import sys

def solve() -> None:
    data = sys.stdin.buffer.read().split()
    it = iter(data)
    t = int(next(it))
    out_lines = []

    for _ in range(t):
        n = int(next(it))
        C = int(next(it))
        v = int(next(it))
        a = [int(next(it)) for _ in range(n)]

        # 计算相邻差并记录最大、最小值
        mx = 0
        mn = float('inf')
        has_zero = False
        gap = []
        for i in range(n - 1):
            diff = a[i + 1] - a[i]
            gap.append(diff)
            if diff > mx:
                mx = diff
            if diff < mn:
                mn = diff
            if diff > C:
                has_zero = True

        # 情况 0：原序列已有差大于 C
        if has_zero:
            out_lines.append("0")
            continue

        # 情况 1：长度为 1 是否可行
        if mx + v > C or mn < v - C:
            out_lines.append("1")
            continue

        # 情况 3：利用左端点累积增量
        ans = float('inf')
        for i in range(n - 1):
            diff = gap[i]
            # 最小长度 L 使得 diff + L * v > C
            need = (C - diff) // v + 1
            # 区间右端点 r = i + need, 要求 r <= n (1-indexed)
            # 0-indexed: 差 i 对应原数组位置 i+1 与 i+2，区间为 [i+2, i+need+1]
            if need <= n - i - 1:
                if need < ans:
                    ans = need

        if ans == float('inf'):
            out_lines.append("-1")
        else:
            out_lines.append(str(ans))

    sys.stdout.write("\n".join(out_lines))

if __name__ == "__main__":
    solve()
```

